  name: 'Pick card · hovered',
  render: () => <Box>
      <PickCard icon={<Icon name="split" />} title="Collector first, then direct" description="Through the collector, direct when none is reachable - and a line long enough to be cut with an ellipsis at the card's edge" aria-label="How it ships: Collector first, then direct. Change" />
    </Box>,
